package handler

// installScriptTemplate renders both installers. Pull mode fetches the
// agent, xray and certificates from the panel with a one-time token; paste
// mode carries the certificates inline and fetches the binaries from their
// GitHub releases, checked against checksums embedded at render time.
const installScriptTemplate = `#!/bin/bash
# NasNet agent installer for node {{.NodeID}} ({{if .Paste}}self-contained{{else}}pull{{end}})
# Generated by the panel. Run as root on the node.
{{- if .Paste}}
# Contains this node's private key: keep it private, delete it after install.
{{- end}}

set -e

RED='\033[0;31m'
GREEN='\033[0;32m'
YELLOW='\033[1;33m'
NC='\033[0m'

log_info() { echo -e "${GREEN}[INFO]${NC} $1"; }
log_warn() { echo -e "${YELLOW}[WARN]${NC} $1"; }
log_error() { echo -e "${RED}[ERROR]${NC} $1"; }

NODE_ID={{.NodeID}}
AGENT_PORT={{.AgentPort}}
CONNECT_MODE={{q .ConnectMode}}
HUB_URL={{q .HubURL}}
NODE_UUID={{q .NodeUUID}}
XRAY_VERSION={{q .XrayVersion}}
{{- if .Paste}}
AGENT_URL_BASE={{q .AgentURLBase}}
{{- else}}
MASTER_URL={{q .MasterURL}}
TOKEN={{q .Token}}
{{- end}}

AGENT_BIN="/usr/local/bin/nasnet-agent"
AGENT_CONFIG_DIR="/etc/nasnet-agent"
AGENT_DATA_DIR="/var/lib/nasnet-agent"
AGENT_LOG_DIR="/var/log/nasnet-agent"
UNINSTALLER="/usr/local/sbin/nasnet-agent-uninstall"
XRAY_BIN="/usr/local/bin/xray"
XRAY_CONFIG="/usr/local/etc/xray/config.json"

if [[ $EUID -ne 0 ]]; then
    log_error "This script must be run as root"
    exit 1
fi

write_uninstaller() {
    mkdir -p "$(dirname "$UNINSTALLER")"
    cat > "$UNINSTALLER" << 'UNINSTALL_EOF'
#!/bin/bash
# Removes the NasNet agent. Xray and its config stay.
set -e
if [[ $EUID -ne 0 ]]; then echo "run as root" >&2; exit 1; fi
systemctl stop nasnet-agent 2>/dev/null || true
systemctl disable nasnet-agent 2>/dev/null || true
# Bandwidth shaping outlives agent restarts; it goes with the agent.
nft delete table inet nasnet_bw 2>/dev/null || true
for dev in $(ls /sys/class/net); do
    { tc filter show dev "$dev" egress; tc filter show dev "$dev" ingress; } 2>/dev/null | grep -q "device nasnet-bw-" || continue
    for hook in egress ingress; do
        for prio in 41001 41002; do tc filter del dev "$dev" "$hook" prio "$prio" 2>/dev/null || true; done
    done
    [ -z "$(tc filter show dev "$dev" egress 2>/dev/null)$(tc filter show dev "$dev" ingress 2>/dev/null)" ] && tc qdisc del dev "$dev" clsact 2>/dev/null || true
done
ip link del nasnet-bw-up 2>/dev/null || true
ip link del nasnet-bw-down 2>/dev/null || true
rm -f /etc/systemd/system/nasnet-agent.service
rm -rf /etc/nasnet-agent /var/lib/nasnet-agent /var/log/nasnet-agent
rm -f /usr/local/bin/nasnet-agent
systemctl daemon-reload
echo "NasNet agent removed (xray and its config were kept)"
rm -f "$0"
UNINSTALL_EOF
    chmod 700 "$UNINSTALLER"
}

if [ "${1:-}" = "--uninstall" ] || [ "${1:-}" = "-u" ]; then
    write_uninstaller
    exec "$UNINSTALLER"
fi

ARCH=$(uname -m)
case $ARCH in
    x86_64) ARCH="amd64" ;;
    aarch64|arm64) ARCH="arm64" ;;
    *) log_error "Unsupported architecture: $ARCH"; exit 1 ;;
esac
OS=$(uname -s | tr '[:upper:]' '[:lower:]')
if [ "$OS" != "linux" ]; then
    log_error "The agent runs on Linux only (detected: $OS)"
    exit 1
fi

sha256_of() {
    if command -v sha256sum >/dev/null 2>&1; then
        sha256sum "$1" | awk '{print $1}'
    elif command -v shasum >/dev/null 2>&1; then
        shasum -a 256 "$1" | awk '{print $1}'
    else
        echo "unknown"
    fi
}

install_packages() {
    if command -v apt-get >/dev/null 2>&1; then
        DEBIAN_FRONTEND=noninteractive apt-get install -y -qq "$@" >/dev/null 2>&1 || \
            { apt-get update -qq >/dev/null 2>&1 && DEBIAN_FRONTEND=noninteractive apt-get install -y -qq "$@" >/dev/null 2>&1; }
    elif command -v dnf >/dev/null 2>&1; then
        dnf install -y -q "$@" >/dev/null 2>&1
    elif command -v yum >/dev/null 2>&1; then
        yum install -y -q "$@" >/dev/null 2>&1
    elif command -v apk >/dev/null 2>&1; then
        apk add --quiet "$@" >/dev/null 2>&1
    else
        return 1
    fi
}

CURL="curl --retry 3 --retry-delay 3 --retry-connrefused -fsSL"

log_info "Installing the NasNet agent for node ${NODE_ID} (${CONNECT_MODE} mode)..."

# Bandwidth shaping uses nftables{{if .Paste}}; unzip unpacks the xray release{{end}}.
NEEDED=""
command -v nft >/dev/null 2>&1 || NEEDED="nftables"
command -v curl >/dev/null 2>&1 || NEEDED="$NEEDED curl"
{{- if .Paste}}
command -v unzip >/dev/null 2>&1 || NEEDED="$NEEDED unzip"
{{- end}}
if [ -n "$NEEDED" ]; then
    log_info "Installing packages:$NEEDED"
    # shellcheck disable=SC2086
    install_packages $NEEDED || log_warn "Could not install:$NEEDED (install them by hand)"
fi

mkdir -p "$AGENT_CONFIG_DIR" "$AGENT_DATA_DIR" "$AGENT_LOG_DIR"

# ---- xray ----
if ! command -v xray >/dev/null 2>&1 && [ ! -f "$XRAY_BIN" ]; then
    log_info "Downloading Xray v${XRAY_VERSION}..."
{{- if .Paste}}
    case $ARCH in
        amd64) XRAY_ASSET="Xray-linux-64.zip"; XRAY_SHA={{q (index .XraySHA "amd64")}} ;;
        arm64) XRAY_ASSET="Xray-linux-arm64-v8a.zip"; XRAY_SHA={{q (index .XraySHA "arm64")}} ;;
    esac
    XRAY_URL="https://github.com/XTLS/Xray-core/releases/download/v${XRAY_VERSION}/${XRAY_ASSET}"
    TMP_ZIP=$(mktemp)
    $CURL -o "$TMP_ZIP" "$XRAY_URL" || { log_error "Failed to download $XRAY_URL"; rm -f "$TMP_ZIP"; exit 1; }
    if [ -z "$XRAY_SHA" ]; then
        # The panel had no cached copy to vouch for; check XTLS's own digest.
        DGST=$($CURL "${XRAY_URL}.dgst" | awk -F'= ' '/256=/{print $2; exit}')
        if [ -z "$DGST" ] || [ "$(sha256_of "$TMP_ZIP")" != "$DGST" ]; then
            log_error "Xray download failed its checksum"
            rm -f "$TMP_ZIP"
            exit 1
        fi
    fi
    unzip -p "$TMP_ZIP" xray > "$XRAY_BIN"
    rm -f "$TMP_ZIP"
    if [ -n "$XRAY_SHA" ] && [ "$(sha256_of "$XRAY_BIN")" != "$XRAY_SHA" ]; then
        log_error "Xray checksum mismatch"
        rm -f "$XRAY_BIN"
        exit 1
    fi
{{- else}}
    HDRS=$(mktemp)
    HTTP_CODE=$($CURL -H "Authorization: Bearer ${TOKEN}" -D "$HDRS" -w "%{http_code}" -o "$XRAY_BIN" \
      "${MASTER_URL}/api/v1/deploy/xray/binary?version=${XRAY_VERSION}&arch=${ARCH}") || HTTP_CODE="000"
    if [ "$HTTP_CODE" != "200" ]; then
        log_error "Failed to download Xray. HTTP Code: $HTTP_CODE"
        rm -f "$XRAY_BIN" "$HDRS"
        exit 1
    fi
    XRAY_SHA=$(awk 'tolower($1)=="x-binary-sha256:"{print $2}' "$HDRS" | tr -d '\r')
    rm -f "$HDRS"
    if [ -z "$XRAY_SHA" ]; then
        # Asked after the binary so the panel's cache is filled by then.
        XRAY_SHA=$($CURL -H "Authorization: Bearer ${TOKEN}" \
          "${MASTER_URL}/api/v1/deploy/xray/checksum?version=${XRAY_VERSION}&arch=${ARCH}" || true)
    fi
    if [[ ! "$XRAY_SHA" =~ ^[0-9a-f]{64}$ ]] || [ "$(sha256_of "$XRAY_BIN")" != "$XRAY_SHA" ]; then
        log_error "Xray checksum mismatch or unavailable"
        rm -f "$XRAY_BIN"
        exit 1
    fi
{{- end}}
    chmod +x "$XRAY_BIN"
    log_info "✓ Xray v${XRAY_VERSION} installed and verified"

    cat > /etc/systemd/system/xray.service << 'XRAYSVC'
[Unit]
Description=Xray Service
Documentation=https://xtls.github.io
After=network.target nss-lookup.target

[Service]
User=root
ExecStart=/usr/local/bin/xray run -config /usr/local/etc/xray/config.json
Restart=on-failure
RestartPreventExitStatus=23
LimitNPROC=10000
LimitNOFILE=1000000

[Install]
WantedBy=multi-user.target
XRAYSVC
    systemctl daemon-reload
    systemctl enable xray
fi

mkdir -p /usr/local/etc/xray /var/log/xray
touch /var/log/xray/access.log /var/log/xray/error.log
chmod 755 /var/log/xray

if [ ! -s "$XRAY_CONFIG" ] || ! grep -q '"api"' "$XRAY_CONFIG" 2>/dev/null; then
    log_info "Creating Xray config with API enabled..."
    cat > "$XRAY_CONFIG" << 'XRAYCONF'
{
  "api": {
    "tag": "api",
    "services": ["HandlerService", "LoggerService", "StatsService", "ReflectionService"]
  },
  "stats": {},
  "policy": {
    "levels": {"0": {"statsUserDownlink": true, "statsUserUplink": true}},
    "system": {
      "statsInboundUplink": true,
      "statsInboundDownlink": true,
      "statsOutboundUplink": true,
      "statsOutboundDownlink": true
    }
  },
  "inbounds": [
    {"listen": "127.0.0.1", "port": 10085, "protocol": "dokodemo-door", "settings": {"address": "127.0.0.1"}, "tag": "api"}
  ],
  "outbounds": [{"protocol": "freedom", "tag": "direct"}],
  "routing": {"rules": [{"type": "field", "inboundTag": ["api"], "outboundTag": "api"}]}
}
XRAYCONF
    chmod 644 "$XRAY_CONFIG"
    systemctl restart xray || true
    sleep 2
fi

# ---- agent binary ----
{{- if .Paste}}
case $ARCH in
    amd64) AGENT_SHA={{q (index .AgentSHA "amd64")}} ;;
    arm64) AGENT_SHA={{q (index .AgentSHA "arm64")}} ;;
esac
if [ -z "$AGENT_SHA" ]; then
    log_error "The panel has no ${ARCH} agent build to vouch for"
    exit 1
fi
if [ -f "$AGENT_BIN" ] && [ "$(sha256_of "$AGENT_BIN")" = "$AGENT_SHA" ]; then
    log_info "✓ Agent binary is already this build"
else
    TMP_AGENT=$(mktemp)
    if [ -n "${AGENT_FILE:-}" ]; then
        # Offline: copy the agent to the node yourself and point AGENT_FILE at it.
        cp "$AGENT_FILE" "$TMP_AGENT"
    elif [ -n "$AGENT_URL_BASE" ]; then
        log_info "Downloading the agent..."
        $CURL -o "$TMP_AGENT" "${AGENT_URL_BASE}/nasnet-agent-linux-${ARCH}" || { log_error "Failed to download the agent"; rm -f "$TMP_AGENT"; exit 1; }
    else
        log_error "This panel is not a release build. Copy bin/agent/nasnet-agent-linux-${ARCH} from the panel and rerun with AGENT_FILE=/path/to/it"
        rm -f "$TMP_AGENT"
        exit 1
    fi
    if [ "$(sha256_of "$TMP_AGENT")" != "$AGENT_SHA" ]; then
        log_error "Agent checksum mismatch"
        rm -f "$TMP_AGENT"
        exit 1
    fi
    systemctl stop nasnet-agent 2>/dev/null || true
    install -m 755 "$TMP_AGENT" "$AGENT_BIN"
    rm -f "$TMP_AGENT"
fi
{{- else}}
REMOTE_CHECKSUM=$($CURL -H "Authorization: Bearer ${TOKEN}" "${MASTER_URL}/api/v1/deploy/binary/checksum?os=${OS}&arch=${ARCH}" || true)
if [[ ! "$REMOTE_CHECKSUM" =~ ^[0-9a-f]{64}$ ]]; then
    log_error "Could not get the agent checksum from the panel"
    exit 1
fi
if [ -f "$AGENT_BIN" ] && [ "$(sha256_of "$AGENT_BIN")" = "$REMOTE_CHECKSUM" ]; then
    log_info "✓ Agent binary is already this build"
else
    log_info "Downloading the agent..."
    TMP_AGENT=$(mktemp)
    HTTP_CODE=$($CURL -H "Authorization: Bearer ${TOKEN}" -w "%{http_code}" -o "$TMP_AGENT" \
      "${MASTER_URL}/api/v1/deploy/binary?os=${OS}&arch=${ARCH}") || HTTP_CODE="000"
    if [ "$HTTP_CODE" != "200" ]; then
        log_error "Failed to download the agent. HTTP Code: $HTTP_CODE"
        rm -f "$TMP_AGENT"
        exit 1
    fi
    if [ "$(sha256_of "$TMP_AGENT")" != "$REMOTE_CHECKSUM" ]; then
        log_error "Agent checksum mismatch"
        rm -f "$TMP_AGENT"
        exit 1
    fi
    systemctl stop nasnet-agent 2>/dev/null || true
    install -m 755 "$TMP_AGENT" "$AGENT_BIN"
    rm -f "$TMP_AGENT"
fi
{{- end}}
log_info "Agent version: $($AGENT_BIN version 2>/dev/null | head -1 || echo 'unknown')"

# ---- certificates ----
{{- if .Paste}}
cat > "${AGENT_CONFIG_DIR}/ca.crt" << 'NASNET_PEM_EOF'
{{.CACert}}
NASNET_PEM_EOF
cat > "${AGENT_CONFIG_DIR}/server.crt" << 'NASNET_PEM_EOF'
{{.AgentCert}}
NASNET_PEM_EOF
(umask 077; cat > "${AGENT_CONFIG_DIR}/server.key" << 'NASNET_PEM_EOF'
{{.AgentKey}}
NASNET_PEM_EOF
)
{{- else}}
log_info "Downloading certificates..."
BUNDLE=$($CURL -H "Authorization: Bearer ${TOKEN}" "${MASTER_URL}/api/v1/certificates/agent/${NODE_ID}/bundle") || {
    log_error "Failed to download certificates"
    exit 1
}

json_val() {
    local json="$1" path="$2"
    if command -v jq &>/dev/null; then
        printf '%s' "$json" | jq -r "$path"
    elif command -v python3 &>/dev/null; then
        printf '%s' "$json" | python3 -c "import sys,json,functools;data=json.load(sys.stdin);print(functools.reduce(lambda d,k:d[k],sys.argv[1].lstrip('.').split('.'),data))" "$path"
    else
        log_error "Neither jq nor python3 found. Please install one: apt-get install -y jq"
        exit 1
    fi
}

printf "%b" "$(json_val "$BUNDLE" .data.ca_cert)" > "${AGENT_CONFIG_DIR}/ca.crt"
printf "%b" "$(json_val "$BUNDLE" .data.agent_cert)" > "${AGENT_CONFIG_DIR}/server.crt"
(umask 077; printf "%b" "$(json_val "$BUNDLE" .data.agent_key)" > "${AGENT_CONFIG_DIR}/server.key")
NODE_UUID=$(json_val "$BUNDLE" .data.node_uuid)
{{- end}}

if ! grep -q "BEGIN CERTIFICATE" "${AGENT_CONFIG_DIR}/server.crt" || [ ! -s "${AGENT_CONFIG_DIR}/server.key" ] || [ ! -s "${AGENT_CONFIG_DIR}/ca.crt" ]; then
    log_error "Certificate files are missing or invalid"
    exit 1
fi
chmod 600 "${AGENT_CONFIG_DIR}/server.key"
chmod 644 "${AGENT_CONFIG_DIR}/ca.crt" "${AGENT_CONFIG_DIR}/server.crt"

# ---- config ----
log_info "Creating configuration..."
if [ "$CONNECT_MODE" = "reverse" ]; then
cat > "${AGENT_CONFIG_DIR}/config.yaml" << CFGEOF
connect_mode: reverse
hub_url: ${HUB_URL}
node_uuid: ${NODE_UUID}
tls:
  enabled: true
  ca_cert: ${AGENT_CONFIG_DIR}/ca.crt
  server_cert: ${AGENT_CONFIG_DIR}/server.crt
  server_key: ${AGENT_CONFIG_DIR}/server.key
xray:
  binary_path: ${XRAY_BIN}
  config_path: ${XRAY_CONFIG}
  api_addr: 127.0.0.1:10085
traffic:
  buffer_enabled: true
  store_path: ${AGENT_DATA_DIR}/traffic.json
CFGEOF
else
cat > "${AGENT_CONFIG_DIR}/config.yaml" << CFGEOF
listen_addr: ":${AGENT_PORT}"
node_uuid: "${NODE_UUID}"

xray:
  binary_path: "${XRAY_BIN}"
  config_path: "${XRAY_CONFIG}"
  api_addr: "127.0.0.1:10085"
  api_timeout: 10
  restart_delay: 1000
  max_restarts: 5
  restart_window: 60

tls:
  enabled: true
  ca_cert: "${AGENT_CONFIG_DIR}/ca.crt"
  server_cert: "${AGENT_CONFIG_DIR}/server.crt"
  server_key: "${AGENT_CONFIG_DIR}/server.key"

logging:
  level: "info"
  format: "text"
  output: "stdout"

process:
  graceful_timeout: 10s
  watchdog_enabled: true
  capture_output: true
  buffer_size: 1000
CFGEOF
fi
chmod 600 "${AGENT_CONFIG_DIR}/config.yaml"

# ---- service ----
log_info "Creating systemd service..."
cat > /etc/systemd/system/nasnet-agent.service << EOSVC
[Unit]
Description=NasNet Agent
After=network.target xray.service
Wants=xray.service

[Service]
Type=simple
User=root
ExecStart=${AGENT_BIN} --config ${AGENT_CONFIG_DIR}/config.yaml
Restart=always
RestartSec=5
StandardOutput=journal
StandardError=journal
SyslogIdentifier=nasnet-agent
LimitNOFILE=65535

[Install]
WantedBy=multi-user.target
EOSVC

write_uninstaller

if [ "$CONNECT_MODE" != "reverse" ] && command -v ufw >/dev/null 2>&1 && ufw status 2>/dev/null | grep -q "Status: active"; then
    ufw allow "${AGENT_PORT}/tcp" >/dev/null && log_info "✓ ufw: opened ${AGENT_PORT}/tcp"
fi

systemctl daemon-reload
systemctl enable nasnet-agent >/dev/null 2>&1
systemctl restart nasnet-agent
sleep 2

if systemctl is-active --quiet nasnet-agent; then
    log_info "✓ Agent installed and running!"
    if timeout 1 bash -c "</dev/tcp/127.0.0.1/10085" >/dev/null 2>&1; then
        log_info "✓ Xray API responding on 127.0.0.1:10085"
    else
        log_warn "Xray API not responding on 127.0.0.1:10085; the panel will show xray as down"
    fi
    log_info ""
    log_info "Commands:"
    log_info "  systemctl status nasnet-agent"
    log_info "  journalctl -u nasnet-agent -f"
    log_info "  ${UNINSTALLER}   # remove the agent"
else
    log_error "Agent failed to start"
    journalctl -u nasnet-agent -n 20 --no-pager || true
    exit 1
fi
`
